create or replace function public.reivindicar_analise(p_segundos integer default 240) returns boolean language plpgsql security definer set search_path = '' as $funcao$ declare v_ok boolean; begin update public.configuracoes_sistema set analise_bloqueada_ate = now() + make_interval(secs => greatest(coalesce(p_segundos, 240), 30)) where id = 1 and (analise_bloqueada_ate is null or analise_bloqueada_ate < now()) returning true into v_ok; return coalesce(v_ok, false); end $funcao$